static __always_inline bool is_high_prio_folio(s32 accessor_nice)
{
    return accessor_nice <= HIGH_PRIO_NICE_MAX;
}

// -- Helper: Compute adaptive thresholds based on CPU contention
static __always_inline void compute_adaptive_params(
    u32 *out_hot_threshold,
    u32 *out_very_hot_threshold,
    u64 *out_recent_ns,
    u64 *out_working_set_ns)
{
    // Default to base values
    *out_hot_threshold = HOT_ACCESS_THRESHOLD_BASE;
    *out_very_hot_threshold = VERY_HOT_ACCESS_THRESHOLD_BASE;
    *out_recent_ns = RECENT_ACCESS_NS_BASE;
    *out_working_set_ns = WORKING_SET_NS_BASE;

    if (sched_nr_running > HIGH_CONTENTION_THRESHOLD) {
        // High contention: tighter windows, lower hot threshold, extend very-hot
        // This means classify more as hot, and protect them much longer
        *out_hot_threshold = 1;              // single access = hot
        *out_very_hot_threshold = 7;         // 7+ accesses = very very hot
        *out_recent_ns = 20000000ULL;        // 20 ms (tighter)
        *out_working_set_ns = 250000000ULL;  // 250 ms (tighter, but extend for high-prio)
    } else if (sched_nr_running > MED_CONTENTION_THRESHOLD) {
        // Medium contention: keep base but be slightly more aggressive
        *out_hot_threshold = 2;              // 2 accesses = hot (same as base)
        *out_very_hot_threshold = 6;         // 6+ accesses = very hot (same as base)
        *out_recent_ns = RECENT_ACCESS_NS_BASE;
        *out_working_set_ns = WORKING_SET_NS_BASE;
    }
    // else: use base values
}

// -- Eviction callback for low-priority list ----
static int bpf_evict_low_prio_cb(int idx, struct cache_ext_list_node *node)
{
    u64 now = bpf_ktime_get_ns();
    u64 key = (u64)node->folio;

    struct sched_folio_metadata *meta =
        bpf_map_lookup_elem(&folio_metadata_map, &key);

    if (!meta)
        return CACHE_EXT_EVICT_NODE;

    // Never evict dirty/writeback pages
    if (folio_test_dirty(node->folio) || folio_test_writeback(node->folio))
        return CACHE_EXT_CONTINUE_ITER;

    u64 age = now - meta->last_access_ts;

    // Get adaptive parameters based on current contention
    u32 hot_threshold, very_hot_threshold;
    u64 recent_ns, working_set_ns;
    compute_adaptive_params(&hot_threshold, &very_hot_threshold, &recent_ns, &working_set_ns);

    // Check actual priority from metadata (handles priority changes)
    bool folio_is_high_prio = is_high_prio_folio(meta->accessor_nice);

    // If folio is actually high-priority but on low-prio list (stale routing),
    // give it extra protection
    if (folio_is_high_prio) {
        if (meta->access_count >= very_hot_threshold) {
            if (age < working_set_ns * 3)
                return CACHE_EXT_CONTINUE_ITER;
        }
        if (meta->access_count >= hot_threshold) {
            if (age < working_set_ns * 2)
                return CACHE_EXT_CONTINUE_ITER;
        }
        if (age < working_set_ns)
            return CACHE_EXT_CONTINUE_ITER;
    }

    // True low-priority folios: aggressive eviction
    if (meta->access_count >= very_hot_threshold) {
        if (age < working_set_ns)
            return CACHE_EXT_CONTINUE_ITER;
    }
    if (meta->access_count >= hot_threshold) {
        if (age < working_set_ns / 2)
            return CACHE_EXT_CONTINUE_ITER;
    }
    if (age < recent_ns)
        return CACHE_EXT_CONTINUE_ITER;

    // Evict old low-prio pages
    if (age > working_set_ns / 2)
        return CACHE_EXT_EVICT_NODE;

    return CACHE_EXT_CONTINUE_ITER;
}

// -- Eviction callback for high-priority list ----
static int bpf_evict_high_prio_cb(int idx, struct cache_ext_list_node *node)
{
    u64 now = bpf_ktime_get_ns();
    u64 key = (u64)node->folio;

    struct sched_folio_metadata *meta =
        bpf_map_lookup_elem(&folio_metadata_map, &key);

    if (!meta)
        return CACHE_EXT_EVICT_NODE;

    // Never evict dirty/writeback pages
    if (folio_test_dirty(node->folio) || folio_test_writeback(node->folio))
        return CACHE_EXT_CONTINUE_ITER;

    u64 age = now - meta->last_access_ts;

    // Get adaptive parameters based on current contention
    u32 hot_threshold, very_hot_threshold;
    u64 recent_ns, working_set_ns;
    compute_adaptive_params(&hot_threshold, &very_hot_threshold, &recent_ns, &working_set_ns);

    // Check actual priority from metadata (handles priority changes)
    bool folio_is_high_prio = is_high_prio_folio(meta->accessor_nice);

    // If folio is actually low-priority but on high-prio list (stale routing),
    // be more aggressive in evicting it
    if (!folio_is_high_prio) {
        if (meta->access_count >= very_hot_threshold && age < working_set_ns)
            return CACHE_EXT_CONTINUE_ITER;
        if (age > working_set_ns / 2)
            return CACHE_EXT_EVICT_NODE;
        if (age > recent_ns)
            return CACHE_EXT_EVICT_NODE;
    }

    // True high-priority folios: strong protection
    if (meta->access_count >= very_hot_threshold) {
        // Under high contention, extend protection significantly
        u64 protection_window = (sched_nr_running > HIGH_CONTENTION_THRESHOLD) ?
                               working_set_ns * 5 : working_set_ns * 3;
        if (age < protection_window)
            return CACHE_EXT_CONTINUE_ITER;
    }

    // Hot folios from high-priority: good protection
    if (meta->access_count >= hot_threshold) {
        u64 protection_window = (sched_nr_running > HIGH_CONTENTION_THRESHOLD) ?
                               working_set_ns * 3 : working_set_ns * 2;
        if (age < protection_window)
            return CACHE_EXT_CONTINUE_ITER;
    }

    // Recently accessed: always protect
    if (age < recent_ns)
        return CACHE_EXT_CONTINUE_ITER;

    // Under contention, extend working-set protection for high-prio
    u64 base_window = (sched_nr_running > HIGH_CONTENTION_THRESHOLD) ?
                     working_set_ns * 2 : working_set_ns;
    if (age < base_window)
        return CACHE_EXT_CONTINUE_ITER;

    return CACHE_EXT_EVICT_NODE;
}

