    *out_very_hot_threshold = VERY_HOT_ACCESS_THRESHOLD_BASE;
    *out_recent_ns = RECENT_ACCESS_NS_BASE;
    *out_working_set_ns = WORKING_SET_NS_BASE;

    if (sched_nr_running > HIGH_CONTENTION_THRESHOLD) {
        // High contention: tighter windows, lower hot threshold, extend very-hot
